    match /boolTrueStringNot/{file} {
      allow create: if !(bool('true') == true);
    }
    match /boolFalseString/{file} {
      allow create: if bool('false') == false;
    }
    match /boolFalseStringNot/{file} {
      allow create: if !(bool('false') == false);
    }
    match /boolUpperString/{file} {
      allow create: if bool('TRUE') == true;
    }
    match /boolUpperStringNot/{file} {
      allow create: if !(bool('TRUE') == true);
    }
    match /boolOneString/{file} {
      allow create: if bool('1') == true;
    }
    match /boolOneStringNot/{file} {
      allow create: if !(bool('1') == true);
    }
    match /boolIntOne/{file} {
      allow create: if bool(1) == true;
    }
    match /boolIntOneNot/{file} {
      allow create: if !(bool(1) == true);
    }
    match /boolIntZero/{file} {
      allow create: if bool(0) == false;
    }
    match /boolIntZeroNot/{file} {
      allow create: if !(bool(0) == false);
    }
    match /boolBool/{file} {
      allow create: if bool(true) == true;
    }
    match /boolBoolNot/{file} {
      allow create: if !(bool(true) == true);
    }
    match /boolNull/{file} {
      allow create: if bool(null) == false;
    }
    match /boolNullNot/{file} {
      allow create: if !(bool(null) == false);
    }
    match /boolList/{file} {
      allow create: if bool([]) == false;
    }
    match /boolListNot/{file} {
      allow create: if !(bool([]) == false);
    }
    match /boolMetadata/{file} {
      allow create: if bool(request.resource.metadata.t) == true;
    }
    match /boolMetadataNot/{file} {
      allow create: if !(bool(request.resource.metadata.t) == true);
    }
    match /boolBare/{file} {
      allow create: if bool('true');
    }
    match /boolIsBool/{file} {
      allow create: if bool('true') is bool;
    }
    match /boolOrTrue/{file} {
      allow create: if bool('true') == true || true;
    }
    match /boolAndFalse/{file} {
      allow create: if !(bool('true') && false);
    }
    match /shadowed/{file} {
      function bool(x) { return x == 'yes'; }
      allow create: if bool('yes');
    }
  }
}

rulesets.bytes-literal:
rules_version = '2';
service firebase.storage {
  match /b/{bucket}/o {
    match /equalsToUtf8/{file} {
      allow create: if b'abc' == 'abc'.toUtf8();
    }
    match /doubleQuoted/{file} {
      allow create: if b"abc" == 'abc'.toUtf8() && b"it's" == 'it\'s'.toUtf8();
    }
    match /upperPrefix/{file} {
      allow create: if B'abc' == b"abc";
    }
    match /emptyLiteral/{file} {
      allow create: if b''.size() == 0 && b'' == ''.toUtf8();
    }
    match /hexEscapeSize/{file} {
      allow create: if b'\x00\x01'.size() == 2;
    }
    match /hexEscapeNotText/{file} {
      allow create: if b'\x00\x01'.size() == 8;
    }
    match /hexEscapeValue/{file} {
      allow create: if b'\x00\x01'.toHexString() == '0001' && b'\xFf\xfF'.toHexString() == 'FFFF';
    }
    match /hexEscapeTwoDigits/{file} {
      allow create: if b'\x411' == b'A1';
    }
    match /octalEscape/{file} {
      allow create: if b'\101' == 'A'.toUtf8() && b'\012' == b'\n' && b'\377' == b'\xff';
    }
    match /simpleEscapes/{file} {
      allow create: if b'\\\'\"\n\r\t\b\f'.toHexString() == '5C27220A0D09080C';
    }
    match /nonAsciiUtf8/{file} {
      allow create: if b'é' == 'é'.toUtf8() && b'é' == b'\xc3\xa9' && b'日本'.size() == 6;
    }
    match /highByteNotUtf8/{file} {
      allow create: if b'\xe9' == 'é'.toUtf8();
    }
    match /isBytes/{file} {
      allow create: if b'abc' is bytes;
    }
    match /toBase64/{file} {
      allow create: if b'\xff'.toBase64() == '_w==';
    }
    match /notEqualString/{file} {
      allow create: if b'abc' == 'abc';
    }
    match /notEqualBytes/{file} {
      allow create: if b'abc' == b'abd';
    }
    match /ordering/{file} {
      allow create: if b'abc' < b'abd' && b'abc' > b'ab' && b'\x00' < b'\xff';
    }
    match /inList/{file} {
      allow create: if b'abc' in [b'abc'] && !(b'abd' in [b'abc']);
    }
    match /hashing/{file} {
      allow create: if hashing.md5(b'abc') == hashing.md5('abc');
    }
    match /concatError/{file} {
      allow create: if b'abc' + b'd' == b'abcd';
    }
    match /concatErrorOrTrue/{file} {
      allow create: if (b'abc' + b'd' == b'abcd') || true;
    }
    match /indexError/{file} {
      allow create: if b'abc'[0] == 97;
    }
  }
}

rulesets.common-auth-membership:
rules_version = '2';
service firebase.storage {
  match /b/{bucket}/o {
    function isAuthenticated() {
      return request.auth != null;
    }
    function isOwner(userId) {
      return isAuthenticated() && request.auth.uid == userId;
    }
    function hasClaim(claim) {
      return request.auth != null && request.auth.token[claim] != null;
    }
    function hasClaimRole(claim, role) {
      return request.auth != null && request.auth.token[claim] == role;
    }
    function isMemberOf(membersMap) {
      return request.auth != null && request.auth.uid in membersMap;
    }
    function hasRole(membersMap, role) {
      return request.auth != null && membersMap[request.auth.uid] == role;
    }

    match /authenticated/{fileId} {
      allow create: if isAuthenticated();
    }
    match /owners/{ownerId} {
      allow create: if isOwner(ownerId);
    }
    match /claims/{fileId} {
      allow create: if hasClaim('plan');
    }
    match /claim-roles/{fileId} {
      allow create: if hasClaimRole('role', 'editor');
    }
    match /members/{fileId} {
      allow create: if isMemberOf(request.auth.token.members);
    }
    match /member-roles/{fileId} {
      allow create: if hasRole(request.auth.token.members, 'editor');
    }
  }
}

