rulesets.math-namespace:
rules_version = '2';
service firebase.storage {
  match /b/{bucket}/o {
    match /mathAbsInt64Min/{fileId} {
      allow read: if math.abs(-9223372036854775807 - 1) < 0 && math.abs(-9223372036854775807 - 1) == -9223372036854775807 - 1;
    }
    match /mathAbsKeepsType/{fileId} {
      allow read: if math.abs(-2) == 2 && math.abs(-2) is int && math.abs(1) is int && math.abs(-2.5) == 2.5 && math.abs(-2.5) is float && math.abs(-1.0) is float;
    }
    match /mathCeilFloorFloat/{fileId} {
      allow read: if math.ceil(1.5) == 2 && math.ceil(1.5) is float && math.ceil(-1.5) == -1 && math.ceil(-0.5) == 0 && math.floor(-1.5) == -2 && math.floor(2.5) == 2 && math.floor(-0.5) == -1 && math.floor(1) is float && math.ceil(1) is float;
    }
    match /mathCeilIsInt/{fileId} {
      allow read: if math.ceil(1.5) is int;
    }
    match /mathRoundHalfUpInt/{fileId} {
      allow read: if math.round(2.5) == 3 && math.round(-2.5) == -2 && math.round(-1.5) == -1 && math.round(0.5) == 1 && math.round(-0.5) == 0 && math.round(1.4) == 1 && math.round(2.5) is int && math.round(1) is int;
    }
    match /mathRoundHalfAwayFromZero/{fileId} {
      allow read: if math.round(-2.5) == -3;
    }
    match /mathRoundIsFloat/{fileId} {
      allow read: if math.round(2.5) is float;
    }
    match /mathRoundNaNInfinity/{fileId} {
      allow read: if math.round(math.sqrt(-1)) == 0 && math.round(math.pow(0, -1)) > 0;
    }
    match /mathSqrtPowFloat/{fileId} {
      allow read: if math.sqrt(4) == 2.0 && math.sqrt(4) is float && math.sqrt(2) > 1.414 && math.sqrt(2) < 1.415 && math.pow(2, 3) == 8.0 && math.pow(2, 3) is float && math.pow(2, -1) == 0.5 && math.pow(4, 0.5) == 2.0;
    }
    match /mathNaNInfinity/{fileId} {
      allow read: if math.isNaN(math.sqrt(-1)) && !math.isNaN(1) && !math.isNaN(1.0) && !math.isNaN(math.pow(0, -1)) && math.pow(0, -1) > 1000000000.0;
    }
    match /mathAbsString/{fileId} {
      allow read: if !(math.abs('a') == 1);
    }
    match /mathAbsStringOrTrue/{fileId} {
      allow read: if (math.abs('a') == 1) || true;
    }
    match /mathAbsBool/{fileId} {
      allow read: if !(math.abs(true) == 1);
    }
    match /mathAbsNull/{fileId} {
      allow read: if !(math.abs(null) == 1);
    }
    match /mathCeilString/{fileId} {
      allow read: if !(math.ceil('a') == 1);
    }
    match /mathSqrtString/{fileId} {
      allow read: if !(math.sqrt('a') == 1);
    }
    match /mathPowString/{fileId} {
      allow read: if !(math.pow(2, 'a') == 1);
    }
    match /mathIsNaNString/{fileId} {
      allow read: if !math.isNaN('a');
    }
    match /mathAbsTwoArgs/{fileId} {
      allow read: if !(math.abs(1, 2) == 1);
    }
    match /mathSqrtNoArgs/{fileId} {
      allow read: if !(math.sqrt() == 1);
    }
    match /mathIsInfinite/{fileId} {
      allow read: if math.isInfinite(1.0) == false;
    }
    match /mathIsInfiniteOrTrue/{fileId} {
      allow read: if math.isInfinite(1.0) || true;
    }
    match /mathIsInfiniteAndFalse/{fileId} {
      allow read: if !(math.isInfinite(1.0) && false);
    }
  }
}

rulesets.metadata-access:
rules_version = '2';
service firebase.storage {
  match /b/{bucket}/o {
    match /dotted/{fileId} {
      allow get: if resource.metadata.owner == request.auth.uid;
    }
    match /bracket/{fileId} {
      allow get: if resource.metadata['owner'] == request.auth.uid;
    }
    match /bkNe/{fileId} {
      allow get: if resource.metadata['missing'] != 'x';
    }
    match /bkEqNull/{fileId} {
      allow get: if resource.metadata['missing'] == null;
    }
    match /bkNotEq/{fileId} {
      allow get: if !(resource.metadata['missing'] == 'x');
    }
    match /bkOrTrue/{fileId} {
      allow get: if resource.metadata['missing'] == 'x' || true;
    }
    match /reqBkNe/{fileId} {
      allow create: if request.resource.metadata['missing'] != 'x';
    }
    match /reqBkEqNull/{fileId} {
      allow create: if request.resource.metadata['missing'] == null;
    }
  }
}

rulesets.metadata-verbs-and-arithmetic:
rules_version = '2';
service firebase.storage {
  match /b/{bucket}/o {
    match /uploads/{userId}/{fileName} {
      allow create: if request.auth != null
        && request.auth.uid == userId
        && request.method == 'create'
        && request.resource.size < 5 * 1024 * 1024
        && request.resource.size >= 1024
        && request.resource.size <= 10 * 1024 * 1024
        && request.resource.contentType.matches('image/.*')
        && request.resource.metadata.owner == request.auth.uid
        && (request.auth.token.admin == true || request.auth.uid == userId)
        && request.path != null;
      allow update: if request.auth != null
        && resource.size + 0 <= request.resource.size
        && request.resource.size - resource.size >= 0
        && request.resource.size / 1024 >= 1
        && resource.contentType == request.resource.contentType;
      allow list: if request.auth != null;
    }
    match /public/{allPaths=**} {
      allow read: if true;
    }
  }
}

rulesets.ordering-operand-types:
rules_version = '2';
service firebase.storage {
  match /b/{bucket}/o {
    match /intFloat/{fileId} {
      allow read: if resource.size < 3.5 && 2.5 <= resource.size && resource.size >= 3;
    }
    match /stringString/{fileId} {
      allow read: if fileId < 'b' && fileId >= 'a';
    }
    match /intString/{fileId} {
      allow read: if resource.size < fileId;
    }
    match /intStringNot/{fileId} {
      allow read: if !(resource.size < fileId);
    }
    match /stringIntNot/{fileId} {
      allow read: if !(fileId >= resource.size);
    }
    match /stringIntGtNot/{fileId} {
