rulesets.ternary-and-error-absorption:
rules_version = '2';
service firebase.storage {
  match /b/{bucket}/o {
    match /ternary/{fileId} {
      // branch selection by auth state
      allow read: if request.auth != null ? fileId == 'ok.txt' : false;
      // erroring condition (div by zero) → expression errors → DENY,
      // even though BOTH branches are true
      allow update: if (request.resource.size / 0 == 0) ? true : true;
      // the same error absorbed by || → ALLOW
      allow delete: if ((1 / 0 == 0) ? true : true) || true;
    }
  }
}

rulesets.type-checks-is:
rules_version = '2';
service firebase.storage {
  match /b/{bucket}/o {
    match /types/{fileId} {
      allow create: if request.resource.size is int
        && request.resource.contentType is string
        && request.resource.metadata is map
        && fileId.split('-') is list;
      // literal typing: 1.0 is float, 1 is int, and NOT vice versa
      allow update: if 1.0 is float
        && 1 is int
        && !(1 is float)
        && !(1.0 is int);
      // a path wildcard is a string, never an int
      allow delete: if fileId is int;
    }
  }
}

